#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <microhttpd.h>

#define MAX_HEADER_LEN 256
#define DEFAULT_PORT 8080

typedef struct {
    int enable_frame_protection;
    int strict_transport;
    char allowed_origins[MAX_HEADER_LEN];
    int deployment_stage; /* 0=dev, 1=staging, 2=production */
} SecurityConfig;

static SecurityConfig g_config;

static void load_env_config(SecurityConfig *cfg) {
    const char *stage = getenv("DEPLOY_STAGE");
    const char *frame_opt = getenv("X_FRAME_POLICY");
    const char *origins = getenv("ALLOWED_ORIGINS");

    cfg->deployment_stage = 0;
    if (stage) {
        if (strcmp(stage, "production") == 0) cfg->deployment_stage = 2;
        else if (strcmp(stage, "staging") == 0) cfg->deployment_stage = 1;
    }

    /* Frame protection defaults based on deployment stage */
    cfg->enable_frame_protection = 1;
    if (frame_opt && strcmp(frame_opt, "DISABLED") == 0) {
        cfg->enable_frame_protection = 0;
    }

    if (origins) {
        strncpy(cfg->allowed_origins, origins, MAX_HEADER_LEN - 1);
        cfg->allowed_origins[MAX_HEADER_LEN - 1] = '\0';
    } else {
        strncpy(cfg->allowed_origins, "DENY", MAX_HEADER_LEN - 1);
    }
}

static int should_apply_frame_headers(const SecurityConfig *cfg) {
    /* In production, always apply frame headers regardless of config */
    /* In other stages, respect the enable_frame_protection flag */
    if (cfg->deployment_stage >= 2) {
        return cfg->enable_frame_protection;
    }
    return cfg->enable_frame_protection;
}

static int compute_security_level(const SecurityConfig *cfg) {
    int level = 0;
    level += cfg->enable_frame_protection;
    level += cfg->strict_transport;
    level += (cfg->deployment_stage > 0) ? 1 : 0;
    return level;
}

static void apply_security_headers(struct MHD_Response *response,
                                    const SecurityConfig *cfg) {
    int sec_level = compute_security_level(cfg);

    /* Always set basic security headers */
    MHD_add_response_header(response, "X-Content-Type-Options", "nosniff");
    MHD_add_response_header(response, "X-XSS-Protection", "1; mode=block");

    if (cfg->strict_transport) {
        MHD_add_response_header(response,
            "Strict-Transport-Security", "max-age=31536000; includeSubDomains");
    }

    /* Frame protection logic:
     * The should_apply_frame_headers function gates this.
     * For production (stage >= 2), we enforce DENY.
     * For other stages, we use the configured allowed_origins.
     */
    if (should_apply_frame_headers(cfg)) {
        if (cfg->deployment_stage >= 2) {
            /* Production: strict DENY policy */
            MHD_add_response_header(response, "X-Frame-Options", "DENY");
            MHD_add_response_header(response,
                "Content-Security-Policy", "frame-ancestors 'none'");
        } else {
            /* Non-production: use configured origins */
            char csp_value[MAX_HEADER_LEN + 32];
            snprintf(csp_value, sizeof(csp_value),
                     "frame-ancestors %s", cfg->allowed_origins);
            MHD_add_response_header(response, "X-Frame-Options",
                strcmp(cfg->allowed_origins, "DENY") == 0 ? "DENY" : "SAMEORIGIN");
            MHD_add_response_header(response, "Content-Security-Policy", csp_value);
        }
    }
    /* Log security level for CI/CD pipeline monitoring */
    fprintf(stdout, "[security] level=%d frame_protect=%d stage=%d\n",
            sec_level, cfg->enable_frame_protection, cfg->deployment_stage);
}

static enum MHD_Result handle_request(
    void *cls, struct MHD_Connection *connection,
    const char *url, const char *method,
    const char *version, const char *upload_data,
    size_t *upload_data_size, void **con_cls) {

    const char *page = "<html><body><h1>CI/CD Pipeline Dashboard</h1>"
                       "<p>Build Status: OK</p></body></html>";
    struct MHD_Response *response;
    enum MHD_Result ret;

    (void)cls; (void)url; (void)method; (void)version;
    (void)upload_data; (void)upload_data_size; (void)con_cls;

    response = MHD_create_response_from_buffer(
        strlen(page), (void *)page, MHD_RESPMEM_PERSISTENT);
    if (!response) return MHD_NO;

    MHD_add_response_header(response, "Content-Type", "text/html; charset=utf-8");
    apply_security_headers(response, &g_config);

    ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
    MHD_destroy_response(response);
    return ret;
}

int main(int argc, char *argv[]) {
    struct MHD_Daemon *daemon;
    int port = DEFAULT_PORT;

    memset(&g_config, 0, sizeof(g_config));
    load_env_config(&g_config);

    if (argc > 1) {
        port = atoi(argv[1]);
        if (port <= 0 || port > 65535) port = DEFAULT_PORT;
    }

    printf("[init] Starting CI/CD dashboard on port %d (stage=%d)\n",
           port, g_config.deployment_stage);

    daemon = MHD_start_daemon(
        MHD_USE_INTERNAL_POLLING_THREAD, port, NULL, NULL,
        &handle_request, NULL, MHD_OPTION_END);

    if (!daemon) {
        fprintf(stderr, "Failed to start HTTP daemon\n");
        return 1;
    }

    printf("Press ENTER to stop...\n");
    getchar();
    MHD_stop_daemon(daemon);
    return 0;
}
